package parse

import "strings"

// Parse splits s on commas; an empty s gives nil.
func Parse(s string) []string {
	if s == "" {
		return nil
	}
	return strings.Split(s, ",")
}

files.parse/parse_test.go:
package parse

import "testing"

func TestParse(t *testing.T) {
	if got := Parse("a,b"); len(got) != 2 {
		t.Fatalf("Parse = %q", got)
	}
}

func TestParseEmpty(t *testing.T) {
	if got := Parse(""); got != nil {
		t.Fatalf("Parse of empty input = %q, want nil", got)
	}
}
